DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `UpdateDriverRating`(IN driverId INT)
BEGIN
  UPDATE kierowcy k
  SET k.ocena = (
    SELECT AVG(o.ocena) 
    FROM oceny_kierowcow o 
    WHERE o.kierowca_id = driverId
  )
  WHERE k.uzytkownik_id = driverId;
END ;;
DELIMITER ;
